{
  "probability": 0.82,
  "range_low": 0.78,
  "range_high": 0.86,
  "summary": [
    "Early-2026 counts (606 by February) raise the odds of hitting 1,000 Mediterranean deaths by May if pace remains high.",
    "Historical annual Mediterranean tolls (~2,000–2,500) imply a robust spring period could push cumulative to or beyond 1,000.",
    "Key factors include spring weather, SAR capacity/policy, and reporting lags which inject substantial uncertainty into the outcome.",
    "Bayesian updating yields a calibrated posterior around 82%, with an uncertainty range reflecting weather, data revisions, and policy dynamics."
  ],
  "confidence": "medium",
  "narrative": "With a 606-death toll by February 2026 and a typical spring-time toll level, reaching 1,000 by May is plausible but uncertain. Updates to weather, SAR capacity, and data reporting will determine if the 1,000-death threshold is exceeded.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "Reference class is IOM Missing Migrants Project Mediterranean fatalities on the Central/Mediterranean route; anchor probability reflects cautious baseline before spring, informed by 2025 Mediterranean tolls (~2,108) and February 2026 counts."
    },
    "factor_updates": [
      {
        "factor": "March–April 2026 mortality pace on Central Mediterranean route",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "606 deaths by end-February imply a sustained or elevated spring pace is needed to reach 1,000 by May."
      },
      {
        "factor": "Weather and sea-state conditions during spring 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Good crossing conditions can increase traffic and fatalities risk, elevating the chance of hitting the threshold."
      },
      {
        "factor": "Search-and-rescue capacity and policy environment",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Greater SAR capacity or stricter policies reducing crossings could lower fatalities, reducing likelihood of reaching 1,000."
      },
      {
        "factor": "Reporting timeliness and data completeness for 2026",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Early-year tallies often undercount; revisions could push totals toward 1,000 by May."
      },
      {
        "factor": "Historical annual toll patterns for the Mediterranean",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Past years show ~2,000–2,500 deaths annually; a sizeable spring period could achieve 1,000 by May if activity remains elevated."
      }
    ],
    "synthesis_rationale": "These factors were weighted by direction and perceived magnitude to form a coherent Bayesian update: pace and seasonality push probability up; SAR/policy dampen; reporting and history provide secondary adjustments. The resulting posterior of 0.82 reflects a plausible but not certain path with a calibrated uncertainty range."
  }
}

{
  "probability": 0.82,
  "range_low": 0.75,
  "range_high": 0.89,
  "summary": [
    "606 deaths/missing by February 2026 implies a plausible path to 1,000 by May if March–April fatalities stay high or rise.",
    "Historical Mediterranean totals (~2,000–2,500/year) set a high baseline that makes a spring surge plausible but not guaranteed.",
    "Uncertainty remains due to weather, SAR capacity/policies, and reporting lags that could push totals up or down."
  ],
  "confidence": "high",
  "narrative": "Early-2026 data show a pronounced pace in Mediterranean fatalities, making the 1,000-by-May threshold plausible. The outcome hinges on spring conditions, rescue capacity, and timely data revisions, which together yield a credible, but uncertain, path to the target.",
  "justification": {
    "anchor": {
      "probability": 0.40,
      "basis": "reference class anchor: IOM Missing Migrants Project Mediterranean fatalities on Central/Mediterranean routes; historical annual tolls around 2,000–2,500 per year; 606 deaths by Feb 2026 used as baseline."
    },
    "factor_updates": [
      {
        "factor": "Early-2026 pace (606 dead/missing by February 2026)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A pace of 606 by February implies substantial fatalities could accumulate by May if March–April remain elevated."
      },
      {
        "factor": "Historical Mediterranean toll around 2,000–2,500 per year",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Annual scale supports a non-trivial chance of reaching 1,000 by May given a strong spring period."
      },
      {
        "factor": "Data reporting lag and revisions",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Early-year counts often undercount; revisions could push cumulative totals higher toward the May target."
      },
      {
        "factor": "Seasonal weather and crossing propensity in spring",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Better spring sea conditions can increase crossings and fatalities, elevating the risk of hitting 1,000 by May."
      },
      {
        "factor": "Policy/regulatory crackdown effects on crossing risk",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Policy effects are uncertain in the near term and may modestly dampen or have mixed effects on fatalities."
      }
    ],
    "synthesis_rationale": "Starting from the anchor probability, the combination of a high early-2026 pace, a large annual baseline, plausible data revisions, and spring weather risks provides a coherent upward drift toward the 1,000-by-May threshold. However, policy dynamics and reporting lags introduce notable uncertainty, keeping the posterior well below certainty and reflected in the calibrated range (0.75–0.89)."
  }
}

